// @ts-ignore `.open-next/worker.js` is generated by the Cloudflare build.
import generatedWorker from "./.open-next/worker.js";
import { getRetiredLegacyProductRedirect } from "./src/lib/catalog-legacy-redirects";
import { deliverQueuedLead, type LeadDeliveryEnvironment, type LeadDeliveryMessage } from "./src/lib/lead-delivery-worker";

interface WorkerEnv extends LeadDeliveryEnvironment {
  GIACONG_VN_CATALOG?: CatalogDatabase;
}

interface CatalogPreparedStatement {
  bind(...values: unknown[]): CatalogPreparedStatement;
  first<T = Record<string, unknown>>(): Promise<T | null>;
  run(): Promise<unknown>;
}

interface CatalogDatabase {
  prepare(query: string): CatalogPreparedStatement;
}

interface QueueMessage<T> {
  body: T;
  retry(options?: { delaySeconds?: number }): void;
}

interface QueueBatch<T> {
  messages: QueueMessage<T>[];
  queue: string;
}

interface WorkerExecutionContext {
  passThroughOnException(): void;
  waitUntil(promise: Promise<unknown>): void;
}

const nonIndexableHosts = new Set([
  "admin-staging.kienhieu.id.vn",
  "admin.kienhieu.id.vn",
  "staging.kienhieu.id.vn",
]);

const PUBLIC_DOCUMENT_CACHE_CONTROL = "public, max-age=0, s-maxage=600, stale-while-revalidate=3600";
const publicDocumentCache = (caches as CacheStorage & { default: Cache }).default;

function isPublicDocumentRequest(request: Request): boolean {
  if (request.method !== "GET") return false;

  const url = new URL(request.url);
  if (url.hostname.toLowerCase() !== "kienhieu.id.vn") return false;
  if (!(request.headers.get("Accept") ?? "").includes("text/html")) return false;
  if (request.headers.has("RSC") || url.searchParams.has("_rsc")) return false;
  if (request.headers.has("Cookie") || request.headers.has("Authorization")) return false;
  return true;
}

function isPublicDocumentResponse(response: Response): boolean {
  if (response.status !== 200) return false;
  if (!(response.headers.get("Content-Type") ?? "").includes("text/html")) return false;
  return !response.headers.has("Set-Cookie");
}

function withPublicDocumentCache(request: Request, response: Response): Response {
  if (!isPublicDocumentRequest(request) || !isPublicDocumentResponse(response)) return response;

  const headers = new Headers(response.headers);
  headers.set("Cache-Control", PUBLIC_DOCUMENT_CACHE_CONTROL);
  headers.delete("Pragma");
  headers.delete("Expires");
  return new Response(response.body, {
    headers,
    status: response.status,
    statusText: response.statusText,
  });
}

function publicDocumentCacheKey(request: Request): Request {
  return new Request(new URL(request.url).toString(), { method: "GET" });
}

async function readPublicDocumentCache(request: Request): Promise<Response | null> {
  if (!isPublicDocumentRequest(request)) return null;
  try {
    return await publicDocumentCache.match(publicDocumentCacheKey(request)) ?? null;
  } catch (error) {
    console.warn("Public document cache read unavailable.", error);
    return null;
  }
}

function writePublicDocumentCache(
  request: Request,
  response: Response,
  ctx: WorkerExecutionContext,
): void {
  if (!isPublicDocumentRequest(request) || !isPublicDocumentResponse(response)) return;
  ctx.waitUntil(
    publicDocumentCache.put(publicDocumentCacheKey(request), response.clone()).catch((error: unknown) => {
      console.warn("Public document cache write unavailable.", error);
    }),
  );
}

function shouldPreventIndexing(request: Request): boolean {
  return nonIndexableHosts.has(new URL(request.url).hostname.toLowerCase());
}

function withIndexingHeaders(request: Request, response: Response): Response {
  if (!shouldPreventIndexing(request)) return response;
  const headers = new Headers(response.headers);
  headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
  return new Response(response.body, {
    headers,
    status: response.status,
    statusText: response.statusText,
  });
}

function catalogProductSlug(pathname: string): string | null {
  const match = /^\/san-pham\/([^/]+)$/.exec(pathname);
  if (!match?.[1]) return null;
  try {
    const slug = decodeURIComponent(match[1]).trim();
    return slug || null;
  } catch {
    return null;
  }
}

async function isPublicCatalogProduct(database: CatalogDatabase, slug: string): Promise<boolean | null> {
  try {
    const row = await database.prepare(
      "SELECT id FROM products WHERE slug = ? AND is_active = 1 LIMIT 1",
    ).bind(slug).first<{ id: number }>();
    return row !== null;
  } catch (error) {
    console.error("Catalog visibility lookup failed.", error);
    return null;
  }
}

async function withCatalogProductNotFoundStatus(
  request: Request,
  response: Response,
  env: WorkerEnv,
): Promise<Response> {
  if ((request.method !== "GET" && request.method !== "HEAD") || response.status !== 200) return response;

  const slug = catalogProductSlug(new URL(request.url).pathname);
  if (!slug || !env.GIACONG_VN_CATALOG) return response;

  const isPublic = await isPublicCatalogProduct(env.GIACONG_VN_CATALOG, slug);
  if (isPublic !== false) return response;

  const headers = new Headers(response.headers);
  return new Response(response.body, {
    headers,
    status: 404,
    statusText: "Not Found",
  });
}

const worker = {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerExecutionContext): Promise<Response> {
    if (request.method === "GET" || request.method === "HEAD") {
      const redirect = getRetiredLegacyProductRedirect(new URL(request.url));
      if (redirect) {
        return withIndexingHeaders(
          request,
          new Response(null, { headers: { Location: redirect }, status: 308 }),
        );
      }
    }

    const cachedDocument = await readPublicDocumentCache(request);
    if (cachedDocument) return cachedDocument;

    const response = await generatedWorker.fetch(request, env, ctx);
    const catalogResponse = await withCatalogProductNotFoundStatus(request, response, env);
    const finalResponse = withPublicDocumentCache(
      request,
      withIndexingHeaders(request, catalogResponse),
    );
    writePublicDocumentCache(request, finalResponse, ctx);
    return finalResponse;
  },

  async queue(batch: QueueBatch<LeadDeliveryMessage>, env: WorkerEnv): Promise<void> {
    if (!env.GIACONG_VN_CATALOG) throw new Error("Missing GIACONG_VN_CATALOG binding.");
    for (const message of batch.messages) {
      try {
        await deliverQueuedLead(message.body, env, env.GIACONG_VN_CATALOG);
      } catch (error) {
        message.retry({ delaySeconds: 60 });
        console.error("Lead queue delivery failed.", {
          error: error instanceof Error ? error.message : "unknown_error",
          leadId: message.body.leadId,
          queue: batch.queue,
        });
      }
    }
  },
};

export default worker;
